// Asset slots.
//
// Everything in the game works without external files: sounds are synthesised,
// pictures are generated by tools/gen_photos.py. This manifest is where real
// assets plug in later, without touching game code.
//
// sounds  — replace a synthesised sound with a recorded file.
//           Key = sound name used in code (see SOUNDS in js/core/audio.js),
//           value = path under src/assets/ (a language may override it, see languages.js).
//           Example:  startup: 'sfx/startup.ogg'
//
// Supported names: startup, shutdown, logon, ding, exclaim, notify, click, type,
// hdd, hddDeath, static, staticShort, glitch, scare, sting, thump, heartbeat,
// whisper, jingle, blip.
window.G = window.G || {};
G.ASSETS = {
  sounds: {
  }
};
